
.target-panel {
  padding: 18px;
  border-radius: 22px;
  border: 1px solid rgba(216, 176, 88, 0.14);
  background:
    linear-gradient(180deg, rgba(29, 21, 14, 0.58), rgba(14, 18, 25, 0.92)),
    rgba(16, 20, 28, 0.94);
}

.section-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 10px;
  margin-bottom: 16px;
}

.section-title {
  color: var(--rr-gold);
  font-family: 'Orbitron', sans-serif;
  font-size: 12px;
  letter-spacing: 2px;
}

.section-subtitle {
  color: var(--rr-text-faint);
  font-size: 12px;
}

.target-name {
  color: var(--rr-text);
  font-size: 26px;
  line-height: 1.2;
  font-weight: 700;
}

.identity {
  margin-top: 8px;
  color: var(--rr-text-soft);
  font-size: 14px;
  line-height: 1.6;
}

.status-stack {
  display: grid;
  gap: 12px;
  margin-top: 18px;
}

.status-card {
  padding: 12px 14px;
  border-radius: 16px;
  border: 1px solid rgba(123, 216, 230, 0.12);
  background: rgba(11, 15, 20, 0.58);
}

.card-label {
  display: block;
  color: var(--rr-text-faint);
  font-size: 11px;
  letter-spacing: 1px;
}

.card-value {
  display: block;
  margin-top: 8px;
  color: var(--rr-text);
  font-size: 15px;
  line-height: 1.5;
}

.safe {
  color: var(--rr-cyan);
}

.warn {
  color: var(--rr-gold);
}

.alert {
  color: #ff93a3;
}

.advice {
  margin-top: 18px;
  padding: 14px;
  border-radius: 18px;
  border: 1px dashed rgba(216, 176, 88, 0.2);
  background: rgba(255, 255, 255, 0.02);
}

.advice-title {
  color: var(--rr-gold);
  font-size: 12px;
  letter-spacing: 2px;
}

.advice-body {
  margin-top: 10px;
  color: var(--rr-text-soft);
  font-size: 13px;
  line-height: 1.7;
}
